import {assert} from './generation-purge-assert.mjs';
import {ArchiveRepository} from '../core/idb-repository.js';

const cases=[],test=(name,fn)=>{if(typeof name!=='string'||typeof fn!=='function')throw Error('native registration');cases.push({name,fn});};
let sequence=0;const repositories=[],ownedNames=new Set();
function nativeOptions(options){if(options?.indexedDB!==indexedDB)throw Error('native factory binding');const name=ownedNames.has(options.name)?options.name:'paia-native-source-purge-multi-matrix-'+(++sequence)+'-'+(options.name||'default');ownedNames.add(name);return {...options,name};}
function nativeStore(storage,options){const store=new LibraryFoundationStore(storage,nativeOptions(options));repositories.push(store.repository);return store;}
function nativeRepository(storage,options){const repository=new ArchiveRepository(storage,nativeOptions(options));repositories.push(repository);return repository;}



export const local = () => { const data = {}; return {async get(k) {return {[k]:structuredClone(data[k])};}, async set(v) {Object.assign(data,structuredClone(v));}}; };
export const capture = (epoch, id = 'm1-synthetic-message-001', text = 'Synthetic explicit working input') => ({epoch,adapterVersion:'0.3.0',chat:{id:'m1-synthetic-chat',url:'https://chatgpt.com/c/m1-synthetic-chat',title:'Synthetic chat'},messages:[{sourceMessageId:id,pageOrder:1,originalText:text}]});
export async function inputEdit(s,id,changes) {const b=await s.input(id);return s.editDocument({operationId:crypto.randomUUID(),documentId:b.documentId,blocks:[{id,expectedRevision:b.revision,libraryText:b.libraryText,note:b.note,excluded:b.excluded,...changes}]});}
export async function derived(s,ids,extra={}) {const evidence=await s.evidenceFor(ids.map(inputId=>({inputId,role:'primary',selectedFields:['body']})));return s.createEntry({operationId:crypto.randomUUID(),actor:'ai',body:'Synthetic conclusion',type:'judgment',formation:ids.length>1?'synthesized':'explicit',evidence,generator:{providerId:'fixture',providerVersion:'1',modelVersion:'deterministic-1',taskSchemaVersion:1,promptTemplateVersion:1,policyVersion:1},...extra});}



import {LibraryFoundationStore} from '../core/thought-store.js';

import {BrowserNativeSyncCore,sealOperation} from '../core/browser-native-sync/core.js';
import {SourceBootstrapJournal} from '../core/browser-native-sync/source-bootstrap-journal.js';
import {SourceBootstrapReceiver} from '../core/browser-native-sync/source-bootstrap-receive.js';
import {SourcePurgeJournal,SourcePurgeReceiver} from '../core/browser-native-sync/source-purge-journal.js';

async function fresh(t,device='synthetic_multi_purge_A'){const s=nativeStore(local(),{indexedDB:indexedDB});await s.consent(true);await s.finishFoundation();t.after(()=>s.repository.db?.close());const core=new BrowserNativeSyncCore(s.repository,{datasetId:'synthetic_multi_source_purge',deviceId:device});s.sourceBootstrapJournal=new SourceBootstrapJournal(core);s.sourcePurgeJournal=new SourcePurgeJournal(core);return {s,core};}
async function sources(t){const f=await fresh(t);for(let n=0;n<2;n++){const q=capture((await f.s.status()).epoch,'synthetic_multi_message_'+n,'SYNTHETIC SOURCE '+n);q.chat={id:'synthetic_purge_chat_'+n,url:'https://chatgpt.com/c/synthetic_purge_chat_'+n,title:'SYNTHETIC separate conversation '+n};await f.s.capture(q);}const snap=await f.s.snapshot();return {...f,selected:snap.records[0],other:snap.records[1]};}
const snapshot=f=>f.s.repository.transaction(false,async tx=>Object.fromEntries(await Promise.all(f.s.repository.stores.map(async name=>[name,await tx.all(name)]))));
const outbox=async core=>{const rows=[];for await(const op of core.outbox())rows.push(op);return rows;};
test('original purge selects one of two independent Source bootstrap groups and preserves the other',async t=>{const f=await sources(t),before=await snapshot(f);assert.equal((await outbox(f.core)).length,14);await f.s.purge(f.selected.id,true);const after=await snapshot(f);assert.deepEqual(after.records,[before.records.find(r=>r.id===f.other.id)]);assert.equal(after.meta.filter(r=>r.id.includes(':revision:')).length,22);assert.equal((await outbox(f.core)).length,15);await f.s.drainPurgeCleanup();assert.ok((await snapshot(f)).revisions.length>0);});
async function groups(core){const operations=[];for await(const row of core.rows('revision'))operations.push(row.operation);return operations.filter(op=>op.type==='sourceBootstrapCommit').map(commit=>[...commit.value.members.map(ref=>operations.find(op=>op.revisionId===ref.revisionId)),commit]);}
async function addSource(f,n){const q=capture((await f.s.status()).epoch,'synthetic_local_'+n,'SYNTHETIC LOCAL '+n);q.chat={id:'synthetic_extra_chat_'+n,url:'https://chatgpt.com/c/synthetic_extra_chat_'+n,title:'SYNTHETIC local independent '+n};await f.s.capture(q);}
function preserved(before,after,selected){const input='block:'+selected.id,doc='document:'+selected.id,sourceKey=selected.sourceKey;for(const table of ['records','recordIndex','blocks','blockIndex','documents','libraryDocuments','times','sourceCounts','filterInputs','inputStates','revisions']){const expected=before[table].filter(row=>!([selected.id,input,doc,sourceKey,JSON.stringify([doc,sourceKey])].includes(row.id))&&!row.sourceRecordIds?.includes(selected.id));for(const row of expected)assert.deepEqual(after[table].find(r=>r.id===row.id),row,table+': unselected row');}}
test('live second device preserves received and local Sources and outbox while consuming only selected remote purge',async t=>{const a=await sources(t),b=await fresh(t,'synthetic_multi_purge_B'),old=await groups(a.core);for(const group of old)await new SourceBootstrapReceiver(b.s,b.core).receive(group);await addSource(b,3);const before=await snapshot(b),queued=await outbox(b.core);assert.equal(queued.length,7);await a.s.purge(a.selected.id,true);const remote=(await outbox(a.core)).filter(op=>op.kind==='purge'||op.type==='sourcePurgeIntent');assert.equal(remote.length,8);assert.equal((await new SourcePurgeReceiver(b.s,b.core).receive(remote)).state,'purged');const after=await snapshot(b);assert.deepEqual(await outbox(b.core),queued);preserved(before,after,a.selected);assert.equal(after.records.length,2);const stable=await snapshot(b);assert.equal((await new SourcePurgeReceiver(b.s,b.core).receive(remote)).state,'duplicate');assert.deepEqual(await snapshot(b),stable);await assert.rejects(new SourceBootstrapReceiver(b.s,b.core).receive(old.find(g=>g.at(-1).value.sourceId===a.selected.id)));assert.deepEqual(await snapshot(b),stable);await b.s.drainPurgeCleanup();const drained=await snapshot(b);preserved(before,drained,a.selected);assert.equal(drained.revisions.length,2);});
for(const mutation of ['record','record-index','input','input-index','document','source-count','history','outbox','archive-index','unexpected-row'])test('late '+mutation+' mutation of an unselected Source rolls back the entire purge',async t=>{const f=await sources(t),before=await snapshot(f),transaction=f.s.repository.transaction.bind(f.s.repository);let injected=false;f.s.repository.transaction=(write,fn,stores)=>transaction(write,async tx=>{const result=await fn(tx);if(write&&result?.id===f.selected.id){injected=true;const table={record:'records','record-index':'recordIndex',input:'blocks','input-index':'blockIndex',document:'documents','source-count':'sourceCounts',history:'revisions',outbox:'meta','archive-index':'meta','unexpected-row':'records'}[mutation];if(mutation==='outbox'){const target=before.meta.find(row=>row.id.includes(':revision:')&&row.operation?.type==='sourceBootstrapMember'&&row.operation.value?.entityType==='source'&&row.operation.value.entity.id===f.other.id);const id=await f.core.idIn(tx,'outbox',target.operation.operationId);await tx.delete('meta',id);}else if(mutation==='archive-index'){const row=before.meta.find(row=>row.id.startsWith('archive-year:v1:row:')&&row.documentId==='document:'+f.other.id);assert.ok(row);await tx.put('meta',{...row,conversationOrder:999});}else if(mutation==='unexpected-row')await tx.put(table,{id:'synthetic-unrepresented',value:{originalText:'SYNTHETIC stray'}});else{const row=before[table].find(row=>row.id===f.other.id||row.id==='block:'+f.other.id||row.id==='document:'+f.other.id||row.documentId==='document:'+f.other.id);assert.ok(row);await tx.delete(table,row.id);}}return result;},stores);await assert.rejects(f.s.purge(f.selected.id,true));assert.equal(injected,true);assert.deepEqual(await snapshot(f),before);});
for(const mutation of ['orphan','fork','reused-member','generation','frontier','device'])test('unselected '+mutation+' protocol invalidity rejects before deleting either Source',async t=>{const f=await sources(t),all=await groups(f.core),other=all.find(g=>g.at(-1).value.sourceId===f.other.id);await f.core.transaction(true,async tx=>{if(mutation==='orphan')await tx.delete('meta',await f.core.idIn(tx,'revision',other[0].revisionId));else if(mutation==='fork'){const row=await f.core.get(tx,'head',other[0].type,other[0].entityId);await tx.put('meta',{...row,revisions:[...row.revisions,all.find(g=>g!==other)[0].revisionId]});}else if(mutation==='reused-member'){const row=await f.core.get(tx,'revision',other.at(-1).revisionId);row.operation.value.members[0]=structuredClone(all.find(g=>g!==other).at(-1).value.members[0]);await tx.put('meta',row);}else{const row=await f.core.get(tx,mutation,...(mutation==='generation'?[]:[f.core.deviceId]));await tx.put('meta',{...row,[mutation==='generation'?'value':mutation==='frontier'?'frontier':'sequence']:999});}});const before=await snapshot(f);await assert.rejects(f.s.purge(f.selected.id,true));assert.deepEqual(await snapshot(f),before);});

test('cryptographically valid cross-group member reuse is rejected by the original compiler',async t=>{const f=await sources(t),all=await groups(f.core),old=all[1].at(-1),value=structuredClone(old.value);value.members[0]=structuredClone(all[0].at(-1).value.members[0]);const forged=await sealOperation({...old,value});await f.core.transaction(true,async tx=>{await tx.delete('meta',await f.core.idIn(tx,'revision',old.revisionId));await f.core.put(tx,'revision',[forged.revisionId],{operation:forged,redacted:false});});const before=await snapshot(f);await assert.rejects(f.s.purge(f.selected.id,true));assert.deepEqual(await snapshot(f),before);});
for(const kind of ['append','other-namespace','resident-checkpoint','unknown-owner'])test('multiple Source purge refuses '+kind+' without deleting any data',async t=>{const f=await sources(t);if(kind==='append'){const q=capture((await f.s.status()).epoch,'synthetic_same_chat_append','SYNTHETIC shared conversation');q.chat={id:f.other.chatId,url:f.other.chatUrl,title:f.other.chatTitle};await f.s.capture(q);}else await f.s.repository.transaction(true,tx=>kind==='other-namespace'?tx.put('meta',{id:f.core.prefix+'generation:other:groupItem:0000',item:{body:'SYNTHETIC other resident body'}}):kind==='resident-checkpoint'?tx.put('meta',{id:'canonical-generation:checkpoint:synthetic',body:'SYNTHETIC checkpoint copy'}):tx.put('thoughts',{id:'synthetic_unknown_owner',body:'SYNTHETIC independent owner'}));const before=await snapshot(f);await assert.rejects(f.s.purge(f.selected.id,true));assert.deepEqual(await snapshot(f),before);});
test('original maintenance callback cannot establish a corrupted unselected source as the new baseline',async t=>{const f=await sources(t),before=await snapshot(f),original=f.s.beforeSourcePurge.bind(f.s);let injected=false;f.s.beforeSourcePurge=async(tx,...args)=>{await original(tx,...args);injected=true;const row=await tx.get('records',f.other.id);await tx.put('records',{...row,value:{...row.value,originalText:'SYNTHETIC corrupt'}});};await assert.rejects(f.s.purge(f.selected.id,true));assert.ok(injected);assert.deepEqual(await snapshot(f),before);});
test('multiple Source purge keeps the private work budget despite resetting public metrics',async t=>{const f=await sources(t),before=await snapshot(f),transaction=f.s.repository.transaction.bind(f.s.repository);let injected=false;f.s.repository.transaction=(write,fn,stores)=>transaction(write,async tx=>{const result=await fn(tx);if(write&&result?.id===f.selected.id){injected=true;for(let i=0;i<4097;i++){tx.metrics.reads=0;await tx.get('meta','synthetic_budget_missing');}}return result;},stores);await assert.rejects(f.s.purge(f.selected.id,true),{code:'BNS_GROUP_RESOURCE_LIMIT'});assert.ok(injected);assert.deepEqual(await snapshot(f),before);});
test('remaining independent Source can be purged after the first cleanup without reviving either group',async t=>{const f=await sources(t),old=await groups(f.core);await f.s.purge(f.selected.id,true);await f.s.drainPurgeCleanup();await f.s.purge(f.other.id,true);await f.s.drainPurgeCleanup();const after=await snapshot(f);assert.equal(after.records.length,0);assert.equal(after.revisions.length,0);assert.equal(after.meta.filter(row=>row.id.startsWith(f.core.prefix+'sourcePurgeDeny:')).length,2);assert.equal((await outbox(f.core)).length,16);for(const group of old)await assert.rejects(new SourceBootstrapReceiver(f.s,f.core).receive(group));assert.deepEqual(await snapshot(f),after);});
test('second selected purge preserves the first queued cleanup and both denial groups',async t=>{const f=await sources(t);await f.s.purge(f.selected.id,true);const before=await snapshot(f),priorJob=before.organizerJobs[0];await f.s.purge(f.other.id,true);const after=await snapshot(f);assert.deepEqual(after.organizerJobs.find(row=>row.id===priorJob.id),priorJob);assert.equal(after.organizerJobs.length,2);assert.equal(after.records.length,0);assert.equal(after.revisions.length,2);await f.s.drainPurgeCleanup();assert.equal((await snapshot(f)).revisions.length,0);});
test('live receiver consumes two selected purges while retaining a local third Source and its queued operations',async t=>{const a=await sources(t),b=await fresh(t,'synthetic_second_purge_B'),old=await groups(a.core);for(const group of old)await new SourceBootstrapReceiver(b.s,b.core).receive(group);await addSource(b,7);const queued=await outbox(b.core);for(const selected of [a.selected,a.other]){await a.s.purge(selected.id,true);const all=await outbox(a.core),descriptor=all.find(op=>op.type==='sourcePurgeIntent'&&op.value.sourceId===selected.id),ids=new Set(descriptor.value.targets.map(target=>target.purgeOperationId)),remote=all.filter(op=>ids.has(op.operationId)||op.operationId===descriptor.operationId);assert.equal((await new SourcePurgeReceiver(b.s,b.core).receive(remote)).state,'purged');assert.equal((await new SourcePurgeReceiver(b.s,b.core).receive(remote)).state,'duplicate');}assert.deepEqual(await outbox(b.core),queued);assert.equal((await b.s.snapshot()).records.length,1);await b.s.drainPurgeCleanup();assert.equal((await snapshot(b)).revisions.length,1);for(const group of old)await assert.rejects(new SourceBootstrapReceiver(b.s,b.core).receive(group));});
for(const kind of ['deny','tombstone','redacted-body','old-outbox','old-receipt','input-state','baseline'])test('prior negative '+kind+' corruption rejects a subsequent purge without altering either group',async t=>{const f=await sources(t);await f.s.purge(f.selected.id,true);await f.s.repository.transaction(true,async tx=>{if(kind==='deny')await tx.delete('meta',f.core.prefix+'sourcePurgeDeny:'+f.selected.sourceKey);else if(kind==='tombstone')await tx.delete('tombstones','source:'+f.selected.sourceKey);else if(kind==='input-state'){const row=await tx.get('inputStates','block:'+f.selected.id);await tx.put('inputStates',{...row,contentRevision:1});}else if(kind==='baseline'){const row=(await tx.all('revisions')).find(row=>row.sourceRecordIds.includes(f.selected.id));await tx.put('revisions',{...row,before:{...row.before,note:'SYNTHETIC hidden history'}});}else{const row=(await tx.all('meta')).find(row=>row.redacted&&row.operation?.actor==='bootstrap');if(kind==='redacted-body')await tx.put('meta',{...row,operation:{...row.operation,value:{body:'SYNTHETIC revived'}}});else if(kind==='old-outbox')await f.core.put(tx,'outbox',[row.operation.operationId],{operationId:row.operation.operationId,revisionId:row.operation.revisionId,state:'queued'});else await tx.delete('meta',await f.core.idIn(tx,'receipt',row.operation.operationId));}});const before=await snapshot(f);await assert.rejects(f.s.purge(f.other.id,true));assert.deepEqual(await snapshot(f),before);});
for(const kind of ['deny','prior-cleanup','prior-tombstone','prior-input-state'])test('late '+kind+' change during the second purge rolls back to the complete first result',async t=>{const f=await sources(t);await f.s.purge(f.selected.id,true);const before=await snapshot(f),transaction=f.s.repository.transaction.bind(f.s.repository);let injected=false;f.s.repository.transaction=(write,fn,stores)=>transaction(write,async tx=>{const result=await fn(tx);if(write&&result?.id===f.other.id){injected=true;if(kind==='deny')await tx.delete('meta',f.core.prefix+'sourcePurgeDeny:'+f.selected.sourceKey);else if(kind==='prior-cleanup')await tx.delete('organizerJobs',before.organizerJobs[0].id);else if(kind==='prior-tombstone')await tx.delete('tombstones','source:'+f.selected.sourceKey);else await tx.delete('inputStates','block:'+f.selected.id);}return result;},stores);await assert.rejects(f.s.purge(f.other.id,true));assert.ok(injected);assert.deepEqual(await snapshot(f),before);});
test('prior baseline with valid shape but changed historical time cannot be authenticated by a later purge',async t=>{const f=await sources(t);await f.s.purge(f.selected.id,true);await f.s.repository.transaction(true,async tx=>{const row=(await tx.all('revisions')).find(row=>row.sourceRecordIds.includes(f.selected.id));await tx.put('revisions',{...row,at:'2026-01-01T00:00:00.000Z',windowStartedAt:'2026-01-01T00:00:00.000Z'});});const before=await snapshot(f);await assert.rejects(f.s.purge(f.other.id,true));assert.deepEqual(await snapshot(f),before);});
test('a canonical change during negative-member digest verification is not adopted as a new baseline',async t=>{const f=await sources(t);await f.s.purge(f.selected.id,true);const digest=crypto.subtle.digest.bind(crypto.subtle);let injected=false;crypto.subtle.digest=async(...args)=>{const text=new TextDecoder().decode(args[1]);if(!injected&&text.includes('baselineRevision')&&text.includes(f.selected.id)&&text.includes('logicalCommitId')){injected=true;await f.s.repository.transaction(true,async tx=>{const row=await tx.get('records',f.other.id);await tx.put('records',{...row,value:{...row.value,note:'SYNTHETIC intervening edit'}});});}return digest(...args);};try{await assert.rejects(f.s.purge(f.other.id,true));assert.ok(injected);assert.equal((await snapshot(f)).records.length,1);assert.equal((await snapshot(f)).meta.filter(row=>row.id.startsWith(f.core.prefix+'sourcePurgeDeny:')).length,1);}finally{crypto.subtle.digest=digest;}});
for(const phase of ['owner-return','tail'])for(const kind of ['existing-meta','new-meta','other-annual','other-outbox'])test('complete metadata cut rejects '+kind+' at '+phase,async t=>{const f=await sources(t);await f.s.repository.transaction(true,tx=>tx.put('meta',{id:'synthetic:optional-metadata',value:'preserve'}));const before=await snapshot(f);let injected=false;const inject=async tx=>{injected=true;if(kind==='existing-meta')await tx.put('meta',{id:'synthetic:optional-metadata',value:'changed'});else if(kind==='new-meta')await tx.put('meta',{id:'synthetic:unplanned-metadata',value:'new'});else if(kind==='other-annual'){const row=before.meta.find(row=>row.id.startsWith('archive-year:v1:row:')&&row.documentId==='document:'+f.other.id);await tx.delete('meta',row.id);}else{const target=before.meta.find(row=>row.operation?.value?.entityType==='source'&&row.operation.value.entity.id===f.other.id);await tx.delete('meta',await f.core.idIn(tx,'outbox',target.operation.operationId));}};if(phase==='owner-return'){const original=f.s.beforeSourcePurge.bind(f.s);f.s.beforeSourcePurge=async(tx,...args)=>{await original(tx,...args);await inject(tx);};}else{const transaction=f.s.repository.transaction.bind(f.s.repository);f.s.repository.transaction=(write,fn,stores)=>transaction(write,async tx=>{const result=await fn(tx);if(write&&result?.id===f.selected.id)await inject(tx);return result;},stores);}await assert.rejects(f.s.purge(f.selected.id,true));assert.ok(injected);assert.deepEqual(await snapshot(f),before);});
test('original reader and disposable index cleanup are replayed while unrelated metadata is preserved',async t=>{const f=await sources(t),selected='block:'+f.selected.id,other='block:'+f.other.id;await f.s.repository.transaction(true,async tx=>{await tx.put('meta',{id:'reading:v1',anchors:[{inputId:selected,offset:20,expanded:[selected,other]},{inputId:other,offset:9,expanded:[other]}]});await tx.put('meta',{id:'synthetic:optional-preserved',value:{counter:3}});await tx.put('meta',{id:'archive-year:v1:build:'+encodeURIComponent('document:'+f.selected.id),epoch:'synthetic',revision:2,complete:false,cursor:selected});await tx.put('meta',{id:'ans:ui:v1',selected:'SYNTHETIC disposable route'});});await f.s.purge(f.selected.id,true);const after=await snapshot(f);assert.deepEqual(after.meta.find(row=>row.id==='reading:v1').anchors,[{inputId:null,offset:0,expanded:[other]},{inputId:other,offset:9,expanded:[other]}]);assert.deepEqual(after.meta.find(row=>row.id==='synthetic:optional-preserved'),{id:'synthetic:optional-preserved',value:{counter:3}});assert.equal(after.meta.some(row=>row.id==='ans:ui:v1'),false);assert.equal(after.meta.some(row=>row.id==='archive-year:v1:build:'+encodeURIComponent('document:'+f.selected.id)),false);});

const previous=globalThis.__bnsNative;
globalThis.__bnsNative={...previous,async run(command,...args){
 if(command!=="source-purge-multi-matrix")return previous.run(command,...args);
 const passed=[];
 for(const item of cases){const after=[];let failure;
  try{await item.fn({after(fn){if(typeof fn!=='function')throw Error('native after');after.push(fn);}});passed.push(item.name);}
  catch(error){failure=Error(item.name+': '+error.stack);}
  finally{
   for(const fn of after.reverse())try{await fn();}catch(error){failure??=error;}
   for(const repository of repositories.splice(0))try{await repository.close();}catch(error){failure??=error;}
   for(const name of ownedNames){try{await new Promise((resolve,reject)=>{const request=indexedDB.deleteDatabase(name);request.onsuccess=resolve;request.onerror=()=>reject(request.error);request.onblocked=()=>reject(Error('native cleanup blocked'));});}catch(error){failure??=error;}}ownedNames.clear();
  }
  if(failure)throw failure;
 }
 return passed;
}};
